def _contains_cftime_datetimes(data: Any) -> bool:
    """Check if array data contains cftime.datetime objects.

    This is an internal helper function that operates on raw array data
    (not xarray.Variable objects).
    """
    if cftime is None:
        return False
    data = np.asarray(data)
    if data.dtype == np.dtype("O") and data.size > 0:
        sample = data.flat[0]
        # Handle dask arrays
        from xarray.namedarray.utils import is_duck_dask_array

        if is_duck_dask_array(sample):
            sample = sample.compute()
            if isinstance(sample, np.ndarray):
                sample = sample.item()
        return isinstance(sample, cftime.datetime)
    return False


